import React, { Component } from 'react'
import PropTypes from 'prop-types'
import ModalImage from 'react-modal-image'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent'
import { PolicyImagesStyle } from './index.style'
import { Col, Row, Upload, Button, Icon } from 'antd'
import getUrlExtension from '../../../../../../helpers/getExtensionUrl'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

class PolicyImages extends Component {
  static propTypes = {
    title: PropTypes.string,
    type: PropTypes.string,
    isShowReuploadBtn: PropTypes.bool,
    isShowRemoveIcon: PropTypes.bool,
    showUploadWithImg: PropTypes.bool,
    data: PropTypes.array,
    onRemoveImg: PropTypes.func,
    onReupload: PropTypes.func
  }

  renderImgContainer = () => {
    const {
      type, data = [], title, isShowReuploadBtn,
      showUploadWithImg, isShowRemoveIcon, onRemoveImg
    } = this.props
    const showReupload = (isShowReuploadBtn && showUploadWithImg)
    return data.map((item, index) => {
      const fileExt = getUrlExtension(item.url)
      return (
        <Col className='img-container' key={`supporting-doc-${index}`}>
          {
            fileExt === 'pdf'
              ? (
                <a href={item.url} target='_blank' rel='noopener noreferrer'>
                  <object
                    type='application/pdf'
                    data={item.url}
                    width='150'
                    height='150'
                    aria-label='PDF'
                  />
                </a>
                )
              : (
                <ModalImage
                  className='policy-img'
                  small={item.url}
                  large={item.url}
                  id={`${type}_${index}`}
                  name={title}
                  imageBackgroundColor='transparent'
                />
                )
          }
          {
            showReupload && (
              <Upload
                name='file'
                accept='.jpg,.png,.jpeg'
                multiple={false}
                showUploadList={false}
                customRequest={({ file }) => this.props.onReupload({
                  data,
                  key: type,
                  oldUrl: item.url,
                  file
                })}
                className='img-reupload-btn'
              >
                Reupload Document
              </Upload>
            )
          }
          {
            isShowReuploadBtn && !showUploadWithImg && isShowRemoveIcon && (
              <div
                className='remove-doc-icon'
                onClick={() => onRemoveImg({
                  data: [
                    ...data
                  ],
                  key: type,
                  oldUrl: item.url
                })}
              >
                <Icon type='close-circle' theme='filled' />
              </div>
            )
          }
        </Col>
      )
    })
  }

  render () {
    const { title, isShowReuploadBtn, type, data = [], showUploadWithImg } = this.props
    return (
      <LayoutContentStyle className='details-info-container policy-detail-card'>
        <Row type='flex' justify='space-between' align='middle'>
          <Col>
            <h3 className='policy-title'>{title}</h3>
          </Col>
          <Col>
            <PermissionCheckerV2 requiredPermission='ops.view_agent_policy_reupload_documents_btn'>
              {
                (isShowReuploadBtn && !showUploadWithImg) && (
                  <Upload
                    name='file'
                    accept='.jpg,.png,.jpeg'
                    multiple={false}
                    showUploadList={false}
                    customRequest={({ file }) => this.props.onReupload({
                      data,
                      key: type,
                      file
                    })}
                  >
                    <Button>Reupload Document</Button>
                  </Upload>
                )
              }
            </PermissionCheckerV2>
          </Col>
        </Row>
        <PolicyImagesStyle>
          <Row type='flex'>
            {
              this.renderImgContainer()
            }
          </Row>
        </PolicyImagesStyle>
      </LayoutContentStyle>
    )
  }
}

export default PolicyImages
